"""Random valid/invalid request generator within the PROTOCOL.md domain."""
import json
import random
import sys
sys.path.insert(0, '/workspace/submission')
from protocol import validate, InvalidRequest


def rand_walk(rng, edges, source, sink):
    # random simple walk source->sink over given edges (bounded attempts)
    for _ in range(60):
        path = []
        cur = source
        seen = {source}
        ok = True
        for _step in range(12):
            outs = [i for i, (u, v, _c) in enumerate(edges) if u == cur and v not in seen]
            if not outs:
                ok = False
                break
            e = rng.choice(outs)
            path.append(e)
            cur = edges[e][1]
            seen.add(cur)
            if cur == sink:
                return path
        if ok and cur == sink:
            return path
    return None


def gen_case(rng, ticket_base=0):
    n = rng.randint(2, 6)
    pairs = [(u, v) for u in range(n) for v in range(n) if u != v]
    rng.shuffle(pairs)
    ne = rng.randint(1, min(12, len(pairs)))
    edges = [[u, v, rng.choice([0, 0, 1, 1, 2, 3, 5, 8, 13])] for (u, v) in pairs[:ne]]
    K = rng.randint(0, 6)
    coms = []
    slots_state = []
    for _ in range(K):
        s, t = rng.sample(range(n), 2)
        d = rng.choice([0, 0, 1, 2, 3, 5, 8, 13])
        nslots = rng.randint(0, 4)
        paths = []
        used = set()
        for _p in range(nslots):
            path = rand_walk(rng, edges, s, t) if rng.random() < 0.85 else None
            key = tuple(path) if path is not None else None
            if path is not None and key in used:
                path = None
            if path is not None:
                used.add(key)
            paths.append(path)
        coms.append({'source': s, 'sink': t, 'demand': d, 'paths': paths})
        slots_state.append(list(paths))
    W = rng.randint(1, 3)
    ids = list(range(K))
    rng.shuffle(ids)
    workers = [[] for _ in range(W)]
    for k in ids:
        workers[rng.randrange(W)].append(k)
    workers = [sorted(w) for w in workers]
    a = rng.randint(1, 8)
    b = rng.randint(1, 8)
    while not (b <= a < 2 * b):
        a = rng.randint(1, 8)
        b = rng.randint(1, 8)
    quorum = rng.randint(1, W)
    max_lag = rng.randint(0, 3)
    rho = rng.randint(1, 8)
    mode = rng.choice(['route', 'admit'])
    events = []
    ticket = ticket_base
    issued = []
    saves = {}
    for _ in range(rng.randint(1, 40)):
        ops = ['issue', 'deliver', 'step', 'audit', 'configure', 'retune', 'save']
        if issued:
            ops += ['deliver'] * 3
        if saves:
            ops += ['restore'] * 2
        if not issued:
            ops = ['issue', 'configure', 'audit', 'save']
        op = rng.choice(ops)
        if op == 'issue':
            ticket += 1
            w = rng.randrange(W)
            events.append({'op': 'issue', 'id': ticket, 'worker': w})
            issued.append(ticket)
        elif op == 'deliver':
            events.append({'op': 'deliver', 'id': rng.choice(issued)})
        elif op == 'step':
            events.append({'op': 'step'})
        elif op == 'audit':
            events.append({'op': 'audit'})
        elif op == 'retune':
            events.append({'op': 'retune', 'rho': rng.randint(1, 8)})
        elif op == 'save':
            name = len(saves) + 1
            saves[name] = True
            events.append({'op': 'save', 'name': name})
        elif op == 'restore':
            events.append({'op': 'restore', 'name': rng.choice(list(saves))})
        else:
            cap = []
            for e in range(len(edges)):
                if rng.random() < 0.15:
                    cap.append([e, rng.choice([0, 0, 1, 1, 2, 5, 9])])
            dem = []
            for k in range(K):
                if rng.random() < 0.15:
                    dem.append([k, rng.choice([0, 0, 1, 3, 7])])
            pathchg = []
            for k in range(K):
                for p in range(len(slots_state[k])):
                    if rng.random() < 0.12:
                        newp = rand_walk(rng, edges, coms[k]['source'], coms[k]['sink']) \
                            if rng.random() < 0.7 else None
                        pathchg.append([k, p, newp])
            # keep distinct within commodities after transaction
            for k in range(K):
                seen = set()
                for c in pathchg:
                    if c[0] == k:
                        slots_state[k][c[1]] = c[2]
                for p, path in enumerate(slots_state[k]):
                    key = tuple(path) if path is not None else None
                    if path is not None:
                        if key in seen:
                            slots_state[k][p] = None
                        else:
                            seen.add(key)
            # fix duplicates in the transaction itself
            fixed = {}
            for c in pathchg:
                if c[2] is not None:
                    fixed[(c[0], c[1])] = tuple(c[2])
            for k in range(K):
                vals = {}
                for p, path in enumerate(slots_state[k]):
                    key = tuple(path) if path is not None else None
                    if path is not None:
                        if key in vals:
                            pathchg.append([k, p, None])
                            slots_state[k][p] = None
                        else:
                            vals[key] = p
            events.append({'op': 'configure', 'mode': rng.choice(['route', 'admit']),
                           'capacity': cap, 'demand': dem, 'paths': pathchg})
    case = {'nodes': n, 'edges': edges, 'commodities': coms, 'workers': workers,
            'quorum': quorum, 'max_lag': max_lag, 'relax': [a, b], 'rho': rho,
            'mode': mode, 'events': events}
    return case, ticket


def gen_request(rng, max_cases=3):
    ncases = rng.randint(0, max_cases)
    cases = []
    base = 0
    for _ in range(ncases):
        case, base = gen_case(rng, base)
        cases.append(case)
    req = {'cases': cases}
    # keep whole-request event/issue totals in domain
    tev = sum(len(c['events']) for c in cases)
    tis = sum(1 for c in cases for e in c['events'] if e['op'] == 'issue')
    if tev > 384 or tis > 48:
        raise ValueError('over budget')
    try:
        validate(json.loads(json.dumps(req)))
    except InvalidRequest:
        raise ValueError('generator produced invalid request!')
    return req
